<?php
namespace App\Http\Controllers;
use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; use Illuminate\Support\Str;
class InvitationController { public function create() { abort_unless(auth()->user()->hasRole('SuperAdmin','Admin'),403); return view('invitations.create'); } public function store(Request $request) { $actor=$request->user(); abort_unless($actor->hasRole('SuperAdmin','Admin'),403); $data=$request->validate(['name'=>'required|string|max:255','email'=>'required|email|unique:users,email','role'=>'required|in:Admin,Member,Sales,Manager','company_id'=>'nullable|integer|exists:companies,id']); if ($actor->hasRole('SuperAdmin') && $data['role']==='Admin' && !empty($data['company_id'])) return back()->withErrors(['role'=>'SuperAdmin cannot invite an Admin into a company.']); if ($actor->hasRole('Admin')) { abort_unless($actor->company_id,403); if (in_array($data['role'],['Admin','Member'],true)) return back()->withErrors(['role'=>'Admin cannot invite an Admin or Member in their company.']); $data['company_id']=$actor->company_id; } if ($actor->hasRole('SuperAdmin') && $data['role']!=='Admin' && empty($data['company_id'])) return back()->withErrors(['company_id'=>'Choose a company for this invitation.']); User::create(['company_id'=>$data['company_id'] ?? null,'name'=>$data['name'],'email'=>$data['email'],'password'=>Hash::make(Str::random(32)),'role'=>$data['role']]); return redirect('/urls')->with('status','User created. Set/reset password flow is not included in this assignment starter.'); } }
